/**
 * Review sheets assembled programmatically from the exact master files (never generated by an
 * image model): one numbered contact sheet of all 105 logical assets, one animation-frame sheet,
 * and an audit table. Missing masters show as labelled empty boxes so gaps are obvious.
 */
import { existsSync } from 'node:fs';
import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import sharp, { type OverlayOptions } from 'sharp';
import { GROUPS, KIND_RULES, type Asset, type Manifest } from './manifest.ts';
import type { RuntimeIndex } from './atlas.ts';
import type { StatusFile } from './status.ts';

const BG = '#ece8df';
const INK = '#2b2620';
const MUTED = '#7a7266';
const FONT = 'DejaVu Sans, Inter, sans-serif';

const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const GROUP_TITLES: Record<(typeof GROUPS)[number], string> = {
  kings: '1. Kings (001-014)',
  friendly: '2. Friendly units (015-026)',
  enemies: '3. Enemies (027-039)',
  buildings: '5. Buildings (040-061)',
  structures: '6. Walls and structures (062-072)',
  effects: '4. Projectiles and effects (073-085)',
  environment: '7. Environment (086-100)',
  map: '8. Map and UI (101-105)',
};

async function thumb(
  file: string,
  box: number,
): Promise<{ png: Buffer; w: number; h: number } | null> {
  if (!existsSync(file)) return null;
  const png = await sharp(file)
    .resize(box, box, { fit: 'inside', withoutEnlargement: false })
    .png()
    .toBuffer();
  const meta = await sharp(png).metadata();
  return { png, w: meta.width ?? box, h: meta.height ?? box };
}

function text(
  x: number,
  y: number,
  s: string,
  size: number,
  color = INK,
  weight = 'normal',
  anchor = 'start',
): string {
  return `<text x="${x}" y="${y}" font-family="${FONT}" font-size="${size}" font-weight="${weight}" fill="${color}" text-anchor="${anchor}">${esc(s)}</text>`;
}

export async function contactSheet(
  root: string,
  manifest: Manifest,
  status: StatusFile,
  outFile: string,
): Promise<void> {
  const cols = 10,
    cell = 196,
    thumbBox = 160,
    labelH = 40,
    headerH = 44,
    margin = 24;
  const layers: OverlayOptions[] = [];
  const svg: string[] = [];
  let y = margin + 70;
  svg.push(
    text(
      margin,
      margin + 30,
      'Kingdom Déchéance: panda assets v1.2, generated masters',
      30,
      INK,
      'bold',
    ),
  );
  const count = manifest.assets.filter((a) =>
    a.parts.every((p) => existsSync(join(root, p.master))),
  ).length;
  svg.push(
    text(
      margin,
      margin + 56,
      `${count}/${manifest.assets.length} logical assets have every master. Frame 1 shown; numbering as on the approved sheet. Built from art/masters by \`pnpm art review\`.`,
      15,
      MUTED,
    ),
  );

  for (const group of GROUPS) {
    const assets = manifest.assets.filter((a) => a.group === group);
    svg.push(text(margin, y + 30, GROUP_TITLES[group], 20, INK, 'bold'));
    y += headerH;
    for (let i = 0; i < assets.length; i++) {
      const a = assets[i] as Asset;
      const cx = margin + (i % cols) * cell;
      const cy = y + Math.floor(i / cols) * (cell + labelH - 20);
      const part = a.parts[0];
      const t = part ? await thumb(join(root, part.master), thumbBox) : null;
      svg.push(
        `<rect x="${cx + 8}" y="${cy}" width="${cell - 16}" height="${thumbBox + 16}" rx="6" fill="#f7f4ee" stroke="#d6d0c4"/>`,
      );
      if (t) {
        layers.push({
          input: t.png,
          left: Math.round(cx + cell / 2 - t.w / 2),
          top: Math.round(cy + 8 + (thumbBox - t.h) / 2),
        });
      } else {
        svg.push(
          text(cx + cell / 2, cy + thumbBox / 2 + 14, 'MISSING', 16, '#a33b2b', 'bold', 'middle'),
        );
      }
      const states = a.parts.map((p) => status.parts[p.id]?.state ?? 'pending');
      const flag = a.inferred ? ' *' : '';
      const frames = a.parts.length > 1 ? ` ×${a.parts.length}` : '';
      svg.push(text(cx + 10, cy + thumbBox + 34, `${a.code} ${a.id}${flag}`, 12, INK, 'bold'));
      svg.push(
        text(cx + 10, cy + thumbBox + 50, `${a.kind}${frames} · ${summarise(states)}`, 11, MUTED),
      );
    }
    y += Math.ceil(assets.length / cols) * (cell + labelH - 20) + 10;
  }

  // Mobile readability strip: ground-standing characters at 40 px tall.
  svg.push(text(margin, y + 30, 'Mobile scale: characters at 40 px tall', 20, INK, 'bold'));
  y += headerH + 6;
  let x = margin;
  for (const a of manifest.assets.filter((m) => ['character', 'flyer', 'siege'].includes(m.kind))) {
    const part = a.parts[0];
    if (!part || !existsSync(join(root, part.master))) continue;
    const png = await sharp(join(root, part.master)).trim().resize({ height: 40 }).png().toBuffer();
    const w = (await sharp(png).metadata()).width ?? 40;
    if (x + w > margin + cols * cell) break;
    layers.push({ input: png, left: x, top: y });
    x += w + 14;
  }
  y += 70;
  svg.push(
    text(
      margin,
      y,
      '* number not on the sheet or ambiguous there: see `inferred` in art/manifest.json.',
      13,
      MUTED,
    ),
  );

  const width = margin * 2 + cols * cell;
  const height = y + margin;
  const base = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}"><rect width="100%" height="100%" fill="${BG}"/>${svg.join('')}</svg>`;
  await sharp(Buffer.from(base)).composite(layers).png({ compressionLevel: 9 }).toFile(outFile);
}

function summarise(states: string[]): string {
  const counts = new Map<string, number>();
  for (const s of states) counts.set(s, (counts.get(s) ?? 0) + 1);
  return [...counts].map(([s, n]) => (states.length > 1 ? `${n} ${s}` : s)).join(', ');
}

export async function animationSheet(
  root: string,
  manifest: Manifest,
  outFile: string,
): Promise<void> {
  const box = 128,
    margin = 24,
    labelW = 280,
    rowH = box + 24;
  const animated = manifest.assets.filter((a) => a.parts.length > 1);
  const maxFrames = Math.max(...animated.map((a) => a.parts.length));
  const svg: string[] = [
    text(margin, margin + 28, 'Animation frames (exact masters, in order)', 26, INK, 'bold'),
  ];
  const layers: OverlayOptions[] = [];
  let y = margin + 50;
  for (const a of animated) {
    svg.push(text(margin, y + box / 2, `${a.code} ${a.id}`, 15, INK, 'bold'));
    svg.push(text(margin, y + box / 2 + 20, a.name, 12, MUTED));
    for (let i = 0; i < a.parts.length; i++) {
      const p = a.parts[i];
      const x = margin + labelW + i * (box + 12);
      svg.push(
        `<rect x="${x}" y="${y}" width="${box}" height="${box}" rx="4" fill="#f7f4ee" stroke="#d6d0c4"/>`,
      );
      svg.push(text(x + 4, y + box + 15, `f${i + 1}`, 11, MUTED));
      const t = p ? await thumb(join(root, p.master), box - 8) : null;
      if (t)
        layers.push({
          input: t.png,
          left: Math.round(x + (box - t.w) / 2),
          top: Math.round(y + (box - t.h) / 2),
        });
      else svg.push(text(x + box / 2, y + box / 2 + 5, 'MISSING', 12, '#a33b2b', 'bold', 'middle'));
    }
    y += rowH;
  }
  const width = margin * 2 + labelW + maxFrames * (box + 12);
  const base = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${y + margin}"><rect width="100%" height="100%" fill="${BG}"/>${svg.join('')}</svg>`;
  await sharp(Buffer.from(base)).composite(layers).png({ compressionLevel: 9 }).toFile(outFile);
}

export interface AuditRow {
  code: string;
  id: string;
  parts: number;
  masters: number;
  runtime: number;
  states: string;
  problems: string[];
}

/** Full file audit: every part needs a master, a runtime frame and a validated or approved state. */
export function audit(
  root: string,
  manifest: Manifest,
  status: StatusFile,
  index: RuntimeIndex | null,
): { rows: AuditRow[]; complete: boolean } {
  const rows = manifest.assets.map((a): AuditRow => {
    const problems: string[] = [];
    let masters = 0,
      runtime = 0;
    for (const p of a.parts) {
      if (existsSync(join(root, p.master))) masters++;
      else problems.push(`${p.id}: no master`);
      if (index?.frames[p.id]) runtime++;
      else problems.push(`${p.id}: not in runtime atlases`);
      const st = status.parts[p.id];
      if (!st || !['validated', 'approved'].includes(st.state))
        problems.push(`${p.id}: ${st?.state ?? 'pending'}`);
      for (const i of st?.issues ?? [])
        if (i.level === 'error') problems.push(`${p.id}: ${i.message}`);
    }
    if (!KIND_RULES[a.kind]) problems.push('unknown kind');
    return {
      code: a.code,
      id: a.id,
      parts: a.parts.length,
      masters,
      runtime,
      states: summarise(a.parts.map((p) => status.parts[p.id]?.state ?? 'pending')),
      problems,
    };
  });
  return { rows, complete: rows.every((r) => r.problems.length === 0) };
}

export async function writeAudit(
  outFile: string,
  manifest: Manifest,
  result: ReturnType<typeof audit>,
): Promise<void> {
  const parts = manifest.assets.reduce((n, a) => n + a.parts.length, 0);
  const done = result.rows.filter((r) => r.problems.length === 0).length;
  const lines = [
    '# Panda art audit',
    '',
    `Generated by \`pnpm art audit\`. ${done}/${manifest.assets.length} logical assets complete; ${parts} generation parts in total.`,
    result.complete ? '**Complete.**' : '**Incomplete**: see the problems column.',
    '',
    '| # | id | parts | masters | runtime | state | problems |',
    '|---|---|---|---|---|---|---|',
    ...result.rows.map((r) => {
      const problems =
        r.problems.length > 3
          ? `${r.problems.slice(0, 3).join('; ')}; +${r.problems.length - 3} more`
          : r.problems.join('; ');
      return `| ${r.code} | ${r.id} | ${r.parts} | ${r.masters} | ${r.runtime} | ${r.states} | ${problems} |`;
    }),
    '',
  ];
  await writeFile(outFile, lines.join('\n'));
}

export async function ensureDir(dir: string): Promise<void> {
  await mkdir(dir, { recursive: true });
}
